            var legacy=SheetSections.raw(draft.getAsJsonObject("sheet"),"proficiencies");legacy.getAsJsonArray("skills").add("medicine");legacy.getAsJsonArray("saves").add("Strength");legacy.getAsJsonArray("saves").add("str");legacy.getAsJsonArray("skills").add("Legacy skill");legacy.getAsJsonArray("languages").add("Elvish");draft=ok(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"proficiencies",legacy));draft=ok(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"creation",choices(List.of(),List.of(),"MANUAL")));reject(api,owner,LIBRARY_FINALIZE,args("character",source.character(),"revision",revision(draft)));
            var selected=CreationRules.skills(clazz.name()).stream().sorted().limit(CreationRules.skillCount(clazz.name())).toList();var expertise=CreationRules.expertiseCount(clazz.name(),1)>0?selected.subList(0,2):List.<String>of();var data=choices(selected,expertise,"MANUAL");draft=ok(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"creation",data));var p=SheetSections.read(draft.getAsJsonObject("sheet"),"proficiencies");for(String skill:selected)check(ProficiencyModel.contains(p,"skills",skill),clazz.name()+" skill grant");for(String save:CreationRules.saves(clazz.name()))check(ProficiencyModel.contains(p,"saves",save),clazz.name()+" mandatory saving throw");check(ProficiencyModel.contains(p,"skills","Medicine")&&ProficiencyModel.contains(p,"skills","Legacy skill"),"Historical grants preserved");check(DashboardModel.strings(p,"saves").size()<=6&&Collections.frequency(DashboardModel.strings(p,"saves"),"str")==1,"Legacy save aliases and mandatory grants are not duplicated");check(!CreationRules.warnings(draft.getAsJsonObject("sheet")).isEmpty(),"Historical grants flagged for review");
            var tooMany=selected.stream().collect(java.util.stream.Collectors.toCollection(ArrayList::new));CreationRules.skills(clazz.name()).stream().filter(v->!tooMany.contains(v)).findFirst().ifPresent(tooMany::add);reject(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"creation",choices(tooMany,expertise,"MANUAL")));for(String invalid:CreationRules.SKILLS)if(!CreationRules.skills(clazz.name()).contains(invalid)){var wrong=new ArrayList<>(selected);wrong.set(0,invalid);reject(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"creation",choices(wrong,expertise,"MANUAL")));break;}
            var forged=SheetSections.raw(draft.getAsJsonObject("sheet"),"proficiencies");forged.getAsJsonArray("skills").add("Athletics");reject(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"proficiencies",forged));reject(api,outsider,LIBRARY_UPDATE,source.sectionArgs(draft,"creation",data));if(expertise.isEmpty())reject(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"creation",choices(selected,List.of(selected.getFirst()),"MANUAL")));else{var invalidExpert=choices(selected,List.of("Survival","Religion"),"MANUAL");reject(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"creation",invalidExpert));var checks=DashboardModel.checks(draft,false);check(checks.stream().filter(c->c.name().equals(expertise.getFirst())).findFirst().orElseThrow().proficiency()==4,"Expertise doubles proficiency exactly once");}
